if not env.company.x_tb_online_token:
    raise UserError('The ANAF service is not active yet: Contacts > Configuration > ANAF > Activate ANAF Service.')
count = 0
for partner in records.filtered('vat'):
    env['x_tb_service_request'].create({
        'x_name': partner.vat,
        'x_service': 'lookup',
        'x_input': partner.vat,
        'x_partner_id': partner.id,
    })
    count += 1
action = {
    'type': 'ir.actions.client',
    'tag': 'display_notification',
    'params': {
        'title': 'ANAF (Terrabit)',
        'message': '%s request(s) sent. The partners are updated in a few seconds.' % count,
        'type': 'info',
    },
}
